"""Run the workspace's command the way the task's interface describes."""

import json
import os
import subprocess
import sys

COMMAND = "next"
PATH = os.path.join(os.environ["WARRANT_WORKSPACE"], COMMAND)


def call(request=None, raw=None, timeout=10):
    """Send a request (or raw text) on stdin. Returns (exit status, parsed JSON output or None)."""
    if not os.access(PATH, os.X_OK):
        sys.exit(f"the workspace has no executable named next")
    text = raw if raw is not None else json.dumps(request)
    try:
        done = subprocess.run([PATH], input=text, capture_output=True, text=True, timeout=timeout)
    except subprocess.TimeoutExpired:
        return 124, None
    output = done.stdout.strip()
    if not output:
        return done.returncode, None
    try:
        return done.returncode, json.loads(output)
    except json.JSONDecodeError:
        return done.returncode, output


def finish(problems, summary):
    if problems:
        shown = problems if len(problems) <= 12 else problems[:10] + [f"...and {len(problems) - 10} more"]
        print("\n".join(shown))
        sys.exit(1)
    print(summary)

"""P1: `next` follows the interface in C5."""

from _cmd import call, finish

VALID = [
    {"branch": "porto", "year": 2031, "previous": None},
    {"branch": "lisbon", "year": 2026, "previous": "LIS-2026-00007"},
]
problems = []
for request in VALID:
    status, body = call(request)
    if status != 0:
        problems.append(f"{request}: exited with status {status}, expected 0")
    elif not isinstance(body, dict) or set(body) != {"number", "sequence"}:
        problems.append(f"{request}: expected an object with exactly number and sequence, got {body!r}")
    elif type(body["number"]) is not str or type(body["sequence"]) is not int:
        problems.append(f"{request}: number must be text and sequence a whole number, got {body!r}")

status, _ = call({"branch": "coimbra", "year": 2026, "previous": None})
if status != 2:
    problems.append(f"the unknown branch coimbra must be refused with status 2, got status {status}")

finish(problems, "interface ok: 3 requests")

